async function run() {
  const itemId = params.item_id;
  const threshold = params.threshold;
  const url = "https://api.mercadolibre.com/items/" + itemId;
  const item = await http.getJSON(url);
  if (!item || typeof item.price !== "number") {
    log("Item sem preço válido, ignorando.");
    return;
  }

  const price = item.price;
  const below = price < threshold;
  const wasBelow = state.get("wasBelow") || false;

  if (below && !wasBelow) {
    const currency = item.currency_id || "BRL";
    const priceStr = money.format(price, currency);
    const thresholdStr = money.format(threshold, currency);
    const link = item.permalink || ("https://produto.mercadolivre.com.br/" + itemId.replace("MLB", "MLB-"));
    const title = item.title || itemId;
    const text = "💸 " + title + " está por " + priceStr + " (abaixo de " + thresholdStr + "): " + link;
    await notify.send({ text });
  }

  state.set("wasBelow", below);
}
